import six
import sys
from abc import ABCMeta, abstractmethod
from taf.analyzer.iperf_throughput.entry import RawEntry


@six.add_metaclass(ABCMeta)
class Filter(object):
    def __init__(self, reader):
        self._reader = reader

    @property
    def reader(self):
        return self._reader

    @property
    def identifiers(self):
        return []

    def do(self):
        with self.reader as read:
            for log_entry in read.log_entries:
                data = self._filter(log_entry)
                if data:
                    yield data

    @abstractmethod
    def _filter(self, log_entry):
        pass

    def on_filter(self, log_entry):
        return self._filter(log_entry)


class RangeFilter(Filter):
    def __init__(self, reader, time_range=None):
        super(RangeFilter, self).__init__(reader)
        self._start = 0.0
        self._end = float(sys.maxsize)
        if isinstance(time_range, tuple):
            boundary_value_count = len(time_range)
            if boundary_value_count == 1:
                self._start = time_range[0]
            elif boundary_value_count == 2:
                self._start = time_range[0]
                self._end = time_range[1]
            else:
                raise AttributeError("not accept tuple with more than 2 values as boundary, received {}".
                                     format(range))

    @property
    def beginning_time(self):
        return self._start

    @property
    def ending_time(self):
        return self._end

    @property
    def customized_range_work(self):
        return self._start != 0.0 or self._end != float(sys.maxsize)

    def _filter(self, log_entry):
        if not hasattr(log_entry, 'interval'):
            return log_entry

        if log_entry.interval.interval_start >= self._start and log_entry.interval.interval_end <= self._end:
            return log_entry


class SingleThreadClientFilter(RangeFilter):
    def __init__(self, reader, time_range=None):
        super(SingleThreadClientFilter, self).__init__(reader, time_range=time_range)

    def _filter(self, log_entry):
        log_entry = super(SingleThreadClientFilter, self)._filter(log_entry)
        return log_entry if not isinstance(log_entry, RawEntry) else None
